FOOTCSS=".ipp-foot{display:flex;flex-wrap:wrap;gap:6px 18px;justify-content:center;margin-top:36px;padding-top:18px;border-top:1px solid var(--line);font-size:.8rem;color:var(--muted)}.ipp-foot a{color:inherit;text-decoration:underline;text-underline-offset:2px}.ipp-foot a:hover{color:var(--accent)}"
