# ---------------------------------------------------------------------------
# Finishing for a standalone website: complete HTML head on the landing page,
# self-hosted fonts instead of Google Fonts, link-preview (Open Graph) tags
# ---------------------------------------------------------------------------
TAGLINE = 'Learn integrated photonics hands-on. Every page is a live simulation in your browser, from light guiding to inverse design.'
def meta(title, desc, path):
    t = title.replace('"', '&quot;'); d = desc.replace('"', '&quot;')
    return (f'<meta name="description" content="{d}">'
            f'<meta property="og:type" content="website"><meta property="og:site_name" content="Photonics Playground">'
            f'<meta property="og:title" content="{t}"><meta property="og:description" content="{d}">'
            f'<meta property="og:url" content="{SITE_URL}{path}"><meta property="og:image" content="{SITE_URL}brand/social-preview.png">'
            f'<meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#0B1228">')

# Cookieless visitor statistics (GoatCounter) and a few anonymous usage events
def analytics():
    if not CONFIG.get('goatcounter'): return ''
    ev = {'#bRun': 'optimize', '#b7run': 'adjoint-loop-run', '#b5chk': 'adjoint-fd-check', '#b3rand': 'adjoint-brute-force',
          '.ipp-tourbtn': 'tour-start', '.ipp-tour [data-a=go]': 'tour-start', '.tab[data-k]': 'component-tab'}
    return ('<script data-goatcounter="' + CONFIG['goatcounter'] + '" async src="https://gc.zgo.at/count.js"></script>'
            '<script>(function(){var EV=' + json.dumps(ev) + ';document.addEventListener("click",function(e){'
            'for(var s in EV){var el=e.target.closest&&e.target.closest(s);if(!el)continue;'
            'var n=EV[s]+(el.dataset&&el.dataset.k?"-"+el.dataset.k:"");var p=location.pathname.split("/").pop()||"index.html";'
            'try{window.goatcounter&&window.goatcounter.count&&window.goatcounter.count({path:"event/"+p.replace(".html","")+"/"+n,title:n,event:true});}catch(_){}break;}},true);})();</script>')
def finish(html, title, desc, path):
    html = html.replace('<meta name="claude:viewport-fit-sides" content="cover">', '')
    html = re.sub(r'<link rel="preconnect" href="https://fonts\.googleapis\.com">\s*', '', html)
    html = re.sub(r'<link rel="stylesheet" href="https://fonts\.googleapis\.com/css2[^"]*">', '<link rel="stylesheet" href="fonts/fonts.css">', html)
    if not html.lstrip().lower().startswith('<!doctype'):
        k = html.index('<div class="wrap">')
        html = ('<!doctype html>\n<html lang="en"><head><meta charset="utf-8">'
                '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n'
                + html[:k] + '</head>\n<body>\n' + html[k:] + '\n</body></html>\n')
    if 'fonts/fonts.css' not in html:
        html = html.replace('</head>', '<link rel="stylesheet" href="fonts/fonts.css"></head>', 1)
    return html.replace('</head>', meta(title, desc, path) + analytics() + '</head>', 1)
pages = [('index.html', 'Photonics Playground', TAGLINE, ''), ('about.html', 'About · Photonics Playground', TAGLINE, 'about.html')]
pages += [(out, name + ' · Photonics Playground', GUIDES[out][2], out) for out, _, _, name in PAGES]
for f, t, d, p in pages:
    html = finish(open(OUT + f).read(), t, d, p)
    open(OUT + f, 'w').write(html)
assert not any('fonts.googleapis' in open(f).read() for f in glob.glob(OUT + '*.html')), 'external font link left'

